-- Vocabulary for every lesson: 20 words and 5 phrasal verbs with Azerbaijani and
-- Russian translations and an example sentence. The [bracketed] part of the example
-- is the gap in the vocabulary test. Readable after the lesson is bought.
-- Generated by supabase/vocab/build.py. Safe to run twice.

create table if not exists lesson_vocab (
  id serial primary key,
  lesson_id int not null references lessons on delete cascade,
  position int not null,
  kind text not null check (kind in ('word', 'phrasal')),
  term text not null,
  az text not null,
  ru text not null,
  example text not null,
  unique (lesson_id, position)
);

alter table lesson_vocab enable row level security;

drop policy if exists "vocab after purchase" on lesson_vocab;
create policy "vocab after purchase" on lesson_vocab for select using (
  exists (select 1 from lesson_purchases p where p.lesson_id = lesson_vocab.lesson_id and p.student_id = auth.uid())
);

insert into lesson_vocab (lesson_id, position, kind, term, az, ru, example)
